WITH cleaned AS (SELECT *, CONCAT_WS('/', txn_type, merchant) AS txn_type_merchant_key, ROUND(amount * 1.15, 2) AS amount_scaled FROM transactions WHERE txn_time > TIMESTAMP '2023-07-07 09:00:00' AND merchant IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS new_group_flag FROM cleaned), sessions_transactions AS (SELECT id, account_id, txn_time, SUM(new_group_flag) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT burst_id, APPROX_PERCENTILE(burst_id, ARRAY(0.25, 0.5, 0.75)) AS burst_id_quartiles, COUNT(DISTINCT id) AS distinct_ids FROM sessions_transactions GROUP BY burst_id ORDER BY burst_id DESC NULLS FIRST
